mapper.select:
select (NVL(DSC_COST_AMT,0)+NVL(TDY_FLOAT_INGPL,0))/SHARE_AMT
from PTL_SEC_VALUTION
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND INV_AIM = '999999'
AND CCY =  #{ccy,jdbcType=VARCHAR}
AND CDATE = to_date(#{tradeDate}, 'yyyy-MM-dd')

select distinct *
from (
         SELECT tpd.UNIT_CPRICE as unitCprice
         FROM TRD_PRODUCT_DEAL tpd
                  LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda
                            ON tpd.TRADE_ID = tpda.TRADE_ID
         WHERE tpd.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
           and tpda.PORTFOLIO_ID = #{portfolioId}
           AND tpd.TRADE_STATUS = #{tardeStatus01,jdbcType=VARCHAR}
           AND tpd.IS_CANCEL = #{yesorno_no}
           AND tpd.TRADE_DATE = to_date(#{tradeDate}, 'yyyy-MM-dd')
           and tpd.ps = 'T02'
         union all
         SELECT tpd.UNIT_CPRICE as unitCprice
         FROM WFL_TRD_PRODUCT_DEAL tpd
                  LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD tpda
                            ON tpd.TRADE_ID = tpda.TRADE_ID
         WHERE tpd.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
           and tpda.PORTFOLIO_ID = #{portfolioId}
           AND tpd.TRADE_DATE = to_date(#{tradeDate}, 'yyyy-MM-dd')
           and tpd.ps = 'T02')

select PROD_REGIST_CODE
from FIN_PRODUCT_ADD T1
         inner join FIN_PRODUCT T2 on T1.FINPROD_ID = T2.FINPROD_ID
where T2.FINPROD_TYPE2 = #{product}
  and T2.FINPROD_MARKET_ID = #{portfolioId}

select CLOSE_PRICE
from MST_EXCHARGE_QUOTE
where BASIS_CYY = #{ccy}
  and QUOT_CYY = #{cny}
  and TRADE_DATE = #{tradDate}

mapper.update:
update
    REP_ASSET_DEPT
set REP_SEND_STATUS = #{YES_OR_NO_Y}
where REP_FINPROD_ID = #{finprodId}
